ST.xhtml:p:
PI := 3.1415926;

fTubeHeight := dSquareWidth;
fTubeWidth := dSquareLenght;
IF fTubeWidth = 0.0 OR fTubeHeight = 0.0 THEN
  RETURN;
ELSE
  fCriticalLength := SQRT(fTubeWidth * fTubeWidth + fTubeHeight * fTubeHeight) / 2.0;
  fCriticalAngle := ATAN(fTubeHeight / fTubeWidth);
END_IF;

nTurns := LREAL_TO_DINT(ABS(fRotationAngle)) / 360;
IF ABS(fRotationAngle) > 360.0 THEN
  fRotationAngleSingleTurn := ABS(fRotationAngle) - DINT_TO_LREAL(nTurns * 360);
ELSE
  fRotationAngleSingleTurn := ABS(fRotationAngle);
END_IF;
fRotationRadSingleTurn := ABS(fRotationAngleSingleTurn) * PI / 180.0;

IF fRotationRadSingleTurn >= 0.0 AND fRotationRadSingleTurn < PI / 2.0 THEN
  fCurrentPos := fCriticalLength * SIN(fRotationRadSingleTurn + fCriticalAngle);
ELSIF fRotationRadSingleTurn >= PI / 2.0 AND fRotationRadSingleTurn < PI THEN
  fCurrentPos := fCriticalLength * SIN(fRotationRadSingleTurn - fCriticalAngle);
ELSIF fRotationRadSingleTurn >= PI AND fRotationRadSingleTurn < PI * 3.0 / 2.0 THEN
  fCurrentPos := fCriticalLength * SIN(fRotationRadSingleTurn + fCriticalAngle - PI);
ELSIF fRotationRadSingleTurn >= PI * 3.0 / 2.0 AND fRotationRadSingleTurn <= PI * 2.0 THEN
  fCurrentPos := fCriticalLength * SIN(fRotationRadSingleTurn - fCriticalAngle - PI);
END_IF;

(*对曲线输出增加滤波*)
fCurrentPosIn := fCurrentPos;
fbCTRL_PT1(
     tCtrlCycleTime := 1.0,
     tT1 := 20.0,
     fIn := fCurrentPosIn,
     fOut => fCurrentPos);
